withAgent<T>(claim:RunContext,binding:Readonly<ApplicationDataBinding>,operation:ApplicationOperationContext,semantics:'read'|'write',work:(context:ApplicationExecutionContext<A>)=>Promise<T>):Promise<T>{
  const known=this.deps.assertRun(claim.run.runId);assertRunApplication(known,binding.appId);const selected=known.snapshot.packages.find(p=>p.packageHash===binding.packageHash&&p.appId===binding.appId);
  const entry=binding.entry??'mcp';
  if(known.plan){const allowed=known.plan.allowed.find(c=>(entry==='cli'?c.capabilityId:c.mcpTool)===binding.toolName&&c.contractMajor===operation.contractMajor&&c.packageHash===binding.packageHash);if(!allowed)throw new ApplicationError('SCOPE_DENIED','固定能力不在运行允许表中');requirePlanEntry(known.plan,allowed.capabilityId,operation.contractMajor,entry);}
  else if(entry==='cli')throw new ApplicationError('SCOPE_DENIED','CLI调用必须有固定运行计划');
  const selectedMajor=entry==='cli'&&known.snapshot.schema===3?known.snapshot.packages.find(p=>p.packageHash===binding.packageHash)?.capabilityContractMajors[binding.toolName]:entry==='mcp'?selected?.toolContractMajors[binding.toolName]:undefined;
  if(known.run.taskId!==claim.run.taskId||known.run.projectId!==claim.run.projectId||!selected||!selected.allowedOperations.includes(binding.permission)||selectedMajor!==operation.contractMajor||(operation.entry??'mcp')!==entry||operation.packageHash!==binding.packageHash||operation.appId!==binding.appId||operation.toolName!==binding.toolName)throw new ApplicationError('SCOPE_DENIED','工具上下文不能替换真实运行、原包或动作');
  const application=this.builtin.assertTrusted(binding.packageHash),appId=this.registry.appId(application.appId),stamp=this.selections.policyStamp(known.run.projectId,appId);
  const check=()=>{const current=this.deps.assertRun(known.run.runId);assertRunApplication(current,binding.appId);if(current.run.taskId!==known.run.taskId||current.run.projectId!==known.run.projectId||canonicalJson(this.selections.policyStamp(known.run.projectId,appId))!==canonicalJson(stamp))throw new ApplicationError('SCOPE_DENIED','当前运行或应用授权已变化');};
  return this.begin(application,{operationId:operation.operationId,callerKind:'agent-run',scopeKind:'project',projectId:known.run.projectId,taskId:known.run.taskId,runId:known.run.runId,jobId:null,parentOperationId:null,appId,packageHash:binding.packageHash,dataApi:1,action:binding.toolName,semantics,allowedOperations:selected.allowedOperations,signal:AbortSignal.any([known.signal,operation.signal]),startedAt:new Date(this.now()).toISOString()},check,stamp,context=>{
    this.agentCalls.set(context,Object.freeze({kind:'agent',operationId:context.operationId,appId,packageHash:binding.packageHash,action:context.action,projectId:known.run.projectId,taskId:known.run.taskId,runId:known.run.runId,entry,requestId:operation.requestId,plan:Object.freeze(known.plan?{kind:'run-plan',hash:known.plan.planHash}:{kind:'snapshot-v2',hash:known.run.snapshotHash})}));

// remain independently queryable. M11 operations retain their original ID and
// are never counted twice. Standalone UI records use the complete PK as an
// opaque identity, so a recycled rowid/request UUID cannot open another run.
const identity="lower(hex(b.run_id))||'_'||lower(hex(b.request_id))",summary="CASE WHEN json_valid(b.summary) THEN b.summary ELSE '{}' END",request="CASE WHEN b.request_id LIKE 'audit:%' THEN substr(b.request_id,7) ELSE b.request_id END";
const trustedMetadata="(b.request_id LIKE 'audit:%' OR b.command LIKE 'ui %' OR b.command='access decision')";
const fields:Record<keyof Row,string>={key:"'browser:'||"+identity,kind:"'browser'",id:identity,app_id:"'browser'",project_id:`COALESCE(CASE WHEN ${trustedMetadata} THEN json_extract(${summary},'$.projectId') END,(SELECT project_id FROM capability_runs WHERE run_id=b.run_id))`,task_id:'b.task_id',run_id:'b.run_id',job_id:'NULL',parent_operation_id:'NULL',caller_kind:`CASE WHEN b.command LIKE 'ui %' AND json_extract(${summary},'$.actor')='user' THEN 'ui' ELSE 'agent-run' END`,action:'b.command',semantics:`CASE WHEN b.request_id LIKE 'audit:%' THEN COALESCE(json_extract(${summary},'$.semantics'),'write') ELSE 'write' END`,state:"CASE WHEN b.state='accepted' THEN 'running' ELSE b.state END",attempt_count:'1',error_code:'b.error_code',effect_state:'b.effect_state',request_id:request,started_at:"strftime('%Y-%m-%dT%H:%M:%fZ',b.created_at/1000.0,'unixepoch')",ended_at:"CASE WHEN b.state IN ('accepted','running') THEN NULL ELSE strftime('%Y-%m-%dT%H:%M:%fZ',b.updated_at/1000.0,'unixepoch') END",targets_json:"'[]'",connection_id:'NULL',subjects_json:"'[]'",draft_id:'NULL',draft_revision:'NULL',execution_id:'NULL',execution_state:'NULL',authorization_source:'NULL',grant_state:'NULL',updated_at:"strftime('%Y-%m-%dT%H:%M:%fZ',b.updated_at/1000.0,'unixepoch')"};
return ledger+' UNION ALL SELECT '+Object.entries(fields).map(([name,value])=>value+' AS '+name).join(',')+` FROM browser_operations b LEFT JOIN tasks t ON t.id=b.task_id

}
const targets=stored(row.targets_json,targetSchema),subjects=stored(row.subjects_json,subjectSchema),ids=new Set([...targets.map(x=>x.id),...subjects.filter(s=>s.kind==='connection').map(s=>s.id),...(row.connection_id?[row.connection_id]:[])]);
const project=row.project_id?this.store.sqlite.prepare('SELECT name FROM projects WHERE id=?').get(row.project_id) as {name:string}|undefined:undefined;
const task=row.task_id?this.store.sqlite.prepare('SELECT title FROM tasks WHERE id=? AND project_id=?').get(row.task_id,row.project_id) as {title:string}|undefined:undefined;
const browser=this.browser(row),metadata=browser?browserActivityDetails(browser):undefined;
return {id:row.id,kind:row.kind,appId:row.app_id,projectId:row.project_id,projectName:project?.name??null,taskId:row.task_id,taskTitle:task?.title??null,runId:row.run_id,jobId:row.job_id,parentOperationId:row.parent_operation_id,callerKind:row.caller_kind,action:row.action,semantics:row.semantics,state:row.state,attemptCount:row.attempt_count,errorCode:row.error_code,effectState:row.effect_state,requestId:row.request_id,startedAt:row.started_at,endedAt:row.ended_at,
 ...(metadata?{browser:{pageId:metadata.pageId,targetTaskId:metadata.targetTaskId,durationMs:metadata.durationMs}}:{}),

export class BrowserAudit {
  constructor(private readonly operations:BrowserOperations){}
  start(scope:{runId:string;requestId:string;taskId:string;projectId:string},command:string,args:Record<string,unknown>,read:boolean){
    const key='audit:'+scope.requestId,record=this.operations.begin(scope.runId,key,scope.taskId,null,command);
    let summary:BrowserCommandAudit={schema:'browser-audit-v1',actor:'agent',projectId:scope.projectId,targetTaskId:typeof args.task==='string'?args.task:scope.taskId,semantics:read?'read':'write',arguments:browserAuditValue(command,args,'arguments'),result:null,authorization:null,authorizations:[],passwordFill:null};
    const save=(state:BrowserOperation['state'],effect:string,code?:string)=>{if(!record.replay)this.operations.update(scope.runId,key,state,effect,{summary,code});};
    save('running',read?'read-only':'not-started');
    return{
      page:(pageId:string)=>{if(!record.replay)this.operations.page(scope.runId,key,pageId);},
      grant:(grant:NonNullable<BrowserCommandAudit['authorization']>,targetTaskId=summary.targetTaskId)=>{summary={...summary,authorization:{...grant},authorizations:[...summary.authorizations.filter(item=>item.grantId!==grant.grantId),{...grant,targetTaskId}]};save('running',read?'read-only':'not-started');},
      passwordFill:(value:boolean)=>{summary={...summary,passwordFill:value};save('running','not-started');},
      pending:(value:unknown)=>{summary={...summary,result:browserAuditValue(command,value,'result')};save('running','unknown');},
      success:(value:unknown)=>{summary={...summary,result:browserAuditValue(command,value,'result')};save('succeeded',read?'read-only':'completed');},
      failure:(error:unknown,dispatched:boolean)=>save(dispatched&&!read?'unknown':'failed',read?'read-only':dispatched?'unknown':'not-started',error instanceof ApplicationError?error.code:'BROWSER_ERROR'),
    };
  }
}
export function browserActivityDetails(row:BrowserOperation):BrowserActivityDetails{
  let summary:unknown=null;try{summary=row.summary===null?null:JSON.parse(row.summary);}catch{throw new ApplicationError('RESOURCE_RECOVERY_REQUIRED','原浏览器审计摘要损坏，未替换为当前结果');}
  if(row.request_id.startsWith('audit:'))summary=protectBrowserSummary(row.command,summary,true);
  const parsed=row.request_id.startsWith('audit:')?browserCommandAuditSchema.safeParse(summary):null;
  if(parsed?.success)return{command:row.command,pageId:row.page_id,targetTaskId:parsed.data.targetTaskId,durationMs:Math.max(0,row.updated_at-row.created_at),arguments:parsed.data.arguments,result:parsed.data.result,authorization:parsed.data.authorization,authorizations:parsed.data.authorizations,passwordFill:parsed.data.passwordFill};
  // Legacy write receipts and trusted UI events have no argument history. A
  // reader still projects their results through the current redaction policy.
  return{command:row.command,pageId:row.page_id,targetTaskId:row.task_id,durationMs:Math.max(0,row.updated_at-row.created_at),arguments:null,result:browserAuditValue(row.command,summary,'result'),authorization:null,passwordFill:null};

activity(pageId:string){const value=this.activities.get(pageId);return{active:!!value&&(value.running.size>0||Date.now()-value.endedAt<20000),running:!!value?.running.size};}
begin(runId:string,taskId:string,pageId:string):()=>void{
  if(this.closed)return()=>{};this.target(runId,taskId);
  let value=this.activities.get(pageId);if(value&&value.taskId!==taskId)throw new ApplicationError('RESOURCE_STATE_CHANGED','页面活动归属不符');
  if(!value){value={taskId,running:new Set(),endedAt:0};this.activities.set(pageId,value);}clearTimeout(value.timer);
  const item=value;let finished=false;
  const token:{runId:string;finish:()=>void}={runId,finish:()=>{
    if(finished)return;finished=true;item.running.delete(token);
    if(this.activities.get(pageId)!==item)return;
    if(!item.running.size){item.endedAt=Date.now();item.timer=setTimeout(()=>{if(this.activities.get(pageId)===item&&!item.running.size){this.activities.delete(pageId);this.changed(taskId);}},20000);item.timer.unref?.();}
    this.changed(taskId);
  }};
  item.running.add(token);this.changed(taskId);return token.finish;
}
forget(pageId:string):void{const value=this.activities.get(pageId);if(!value)return;clearTimeout(value.timer);this.activities.delete(pageId);for(const token of [...value.running])token.finish();this.changed(value.taskId);}
endRun(runId:string):void{
  const run=this.runs.get(runId);if(!run)return;run.binding.signal.removeEventListener('abort',run.stop);this.runs.delete(runId);
  for(const [taskId,ids]of this.pauses)if(ids.delete(runId)&&!ids.size){this.pauses.delete(taskId);this.changed(taskId);}
  for(const value of this.activities.values())for(const token of [...value.running])if(token.runId===runId)token.finish();
  this.options.ended?.(runId);
